SELECT
    user_id AS userId,
    display_name AS displayName
FROM
    users
WHERE
    (
        mobile_number = #{mobileNumber}
        or
        email_id = #{emailId}
        or
        display_name = #{displayName}
    )
    and password = #{password}
    and is_deleted = 'N'

SELECT
    user_id as userId,
    display_name as displayName
FROM
    users
WHERE
    is_deleted = 'N'
    AND (
        email_id = #{emailId}
        OR mobile_number = #{mobileNumber}
        OR display_name = #{displayName}
    )
